import express, { NextFunction, Request, Response } from "express";
import { FulfilmentService, PlaceOrderItem } from "../application/fulfilment-service";
import { DomainError, NotFoundError } from "../domain/errors";
import { OrderState, orderStates } from "../domain/order";

interface ProductBody { id?: unknown; name?: unknown; stock?: unknown }
interface OrderBody { customerId?: unknown; items?: unknown }
interface StateBody { state?: unknown }

const stringValue = (value: unknown, field: string): string => {
  if (typeof value !== "string") throw new DomainError(`${field} must be a string.`);
  return value;
};

export const createHttpServer = (service: FulfilmentService) => {
  const app = express();
  app.use(express.json());

  app.post("/products", (req: Request<unknown, unknown, ProductBody>, res) => {
    const { id, name, stock } = req.body;
    if (typeof stock !== "number") throw new DomainError("stock must be a number.");
    res.status(201).json(service.addProduct(stringValue(id, "id"), stringValue(name, "name"), stock));
  });
  app.get("/products", (_req, res) => res.json(service.listProducts()));

  app.post("/orders", (req: Request<unknown, unknown, OrderBody>, res) => {
    const { customerId, items } = req.body;
    if (!Array.isArray(items)) throw new DomainError("items must be an array.");
    const orderItems: PlaceOrderItem[] = items.map((item) => {
      if (typeof item !== "object" || item === null) throw new DomainError("Each item must be an object.");
      const candidate = item as { productId?: unknown; quantity?: unknown };
      if (typeof candidate.productId !== "string" || typeof candidate.quantity !== "number") {
        throw new DomainError("Each item needs a string productId and numeric quantity.");
      }
      return { productId: candidate.productId, quantity: candidate.quantity };
    });
    res.status(201).json(service.placeOrder(stringValue(customerId, "customerId"), orderItems));
  });
  app.get("/orders", (req, res) => {
    const state = req.query.state;
    if (state !== undefined && (typeof state !== "string" || !orderStates.includes(state as OrderState))) {
      throw new DomainError("state must be one of placed, paid, packed, shipped, delivered.");
    }
    res.json(service.listOrders(state as OrderState | undefined));
  });
  app.get("/orders/:id", (req, res) => res.json(service.getOrder(req.params.id)));
  app.patch("/orders/:id/state", (req: Request<{ id: string }, unknown, StateBody>, res) => {
    const state = req.body.state;
    if (typeof state !== "string" || !orderStates.includes(state as OrderState)) {
      throw new DomainError("state must be one of placed, paid, packed, shipped, delivered.");
    }
    res.json(service.advanceOrder(req.params.id, state as OrderState));
  });
  app.post("/orders/:id/cancel", (req, res) => res.json(service.cancelOrder(req.params.id)));

  app.use((error: unknown, _req: Request, res: Response, _next: NextFunction) => {
    if (error instanceof DomainError) {
      res.status(error instanceof NotFoundError ? 404 : 400).json({ error: error.message });
      return;
    }
    res.status(500).json({ error: "Internal server error." });
  });
  return app;
};

